// @vitest-environment node
import { describe } from "vitest";
import {
  createLocalPortalBrowserSession,
  localQuotePage,
  registerSharedPortalBrowserRefusals,
} from "../../test-support/localPortalBrowserFixture";
import { geomiqDispatchAuthorization, geomiqDispatchEnvelope } from "../../test-support/geomiqDispatchFixture";
import { buildGeomiqProductionPortalDefinition, GEOMIQ_PRODUCTION_LOCATORS } from "./geomiqProductionPortal";

/**
 * Generated by `npm run fixture:onboard -- geomiq --stage=live` (OVD-687).
 *
 * Browser-fixture stub for the Geomiq production definition. It is
 * skipped until a reviewed locator table, upload selector, and eligibility
 * hook replace the generated placeholders and `geomiq` is registered with a
 * portal workflow; the generated stub is unavailable before launch, so these
 * cases cannot pass yet. Synthetic pages only; nothing reaches the network.
 */
describe.skip("Geomiq production portal definition in a browser fixture (pending review)", () => {
  const session = createLocalPortalBrowserSession({
    vendor: "geomiq",
    host: "app.geomiq.com",
    pagePath: "/",
    cadBytes: "synthetic geomiq cad bytes for the browser fixture",
    cookieDomain: "app.geomiq.com",
    tempPrefix: "geomiq-browser-",
    locators: GEOMIQ_PRODUCTION_LOCATORS,
    buildDefinition: buildGeomiqProductionPortalDefinition,
    bindAuthorization: (binding) => {
      const envelope = geomiqDispatchEnvelope(binding);
      return { envelope, authorization: geomiqDispatchAuthorization(envelope) };
    },
  });

  const quotePage = (options: { before?: string; afterUpload?: string; fileInput?: boolean; extraHead?: string } = {}) =>
    localQuotePage({ title: "Geomiq quote", charset: true, ...options });

  registerSharedPortalBrowserRefusals(session, {
    missingCards: quotePage({ afterUpload: "<p>Total: $25.00 in 7 days</p>" }),
    missingCad: quotePage({ fileInput: false }),
    login: quotePage({ before: "<h1>Session expired</h1><p>Please log in again.</p>" }),
    captcha: quotePage({ before: "<p>Please verify you are human</p>" }),
    maintenance: quotePage({ before: "<p>The quote tool is under maintenance</p>" }),
    engineeringReview: quotePage({ afterUpload: "<p>Your part needs a manual review by our engineers.</p>" }),
    thirdParty: quotePage({
      extraHead: "<script src=\"https://cdn.example.com/tracker.js\"></script>",
      afterUpload: session.optionCard({ id: "standard", label: "Standard", quantity: "3", unit: "10.00", total: "30.00", currency: "USD" }),
    }),
  });
});
